 it('rejects concurrent invocation on the same client without a second transaction',async()=>{const r=request(),f=transport(r);let release!:()=>void;f.pause(new Promise<void>(resolve=>{release=resolve;}));const first=executeGuardedTypedLocalBackfill(f.c,r);expect(await executeGuardedTypedLocalBackfill(f.c,r)).toEqual({status:'BLOCKED',code:'CLIENT_ALREADY_IN_USE'});release();expect(await first).toMatchObject({status:'APPLIED'});expect(f.queries.filter(q=>q.text.startsWith('BEGIN'))).toHaveLength(1);});
