// These cases model inert query results only. Actual SQL/transaction/resource
// and same-plan concurrency proofs remain the separate root-owned PG suite.
describe('typed journal whole-plan successor fictional transaction regressions',()=>{
 it.each([['JOURNAL_SCHEMA',0,1,'foreign-owner'],['JOURNAL_TABLES',0,5,'true'],['JOURNAL_FUNCTION',0,2,'true'],['JOURNAL_FUNCTION',0,4,'changed-definition'],['JOURNAL_TRIGGERS',0,4,'D'],['JOURNAL_ACLS',0,3,'0'],['JOURNAL_ACLS',0,5,'DELETE']] as const)('rejects installation %s[%s,%s] drift before BEGIN',async(tag,row,column,value)=>{const r=request(base(),true),f=transport(r,true);f.setMutation((t,rows)=>{if(t===tag)rows[row][column]=value;});expect(await executeGuardedTypedLocalBackfillWithJournal(f.c,r)).toEqual({status:'BLOCKED',code:'TYPED_JOURNAL_INSTALLATION_DRIFT'});expect(f.queries.some(q=>q.text.startsWith('BEGIN'))).toBe(false);expect(f.journalPresent()).toBe(false);});
 it('locks source70 then fixed journal2 before all transaction reads and commits matching structural state',async()=>{const r=request(base(),true),f=transport(r,true),out=await executeGuardedTypedLocalBackfillWithJournal(f.c,r);expect(out,canonicalOwnershipJson(out)).toMatchObject({status:'APPLIED',verification:'OWNED_LOCAL_ATOMIC_TYPED_JOURNAL_BACKFILL_NOT_F10_COMPLETE',journal:{effectsVerified:false}});const begin=f.queries.findIndex(q=>q.text.startsWith('BEGIN')),source=f.queries.findIndex(q=>q.text.startsWith('LOCK TABLE')),j=f.queries.findIndex(q=>q.text.includes('F10_TYPED_JOURNAL_LOCK'));expect(source).toBeGreaterThan(begin);expect(j).toBe(source+1);expect(f.queries.slice(begin+1,source).every(q=>q.text.startsWith('SET '))).toBe(true);expect([...f.journalStates.values()].every(s=>s==='STARTED')).toBe(true);expect(f.queries.findIndex(q=>q.text.includes('F10_TYPED_JOURNAL_START'))).toBeLessThan(f.queries.findIndex(q=>q.text.startsWith('UPDATE public.')));expect(f.queries.at(-1)!.text).toBe('COMMIT');});
 it('exact applied retry reads durable state and issues no source/control/journal DML',async()=>{const r=request(base(),true),f=transport(r,true);expect(await executeGuardedTypedLocalBackfillWithJournal(f.c,r)).toMatchObject({status:'APPLIED'});const n=f.queries.length;expect(await executeGuardedTypedLocalBackfillWithJournal(f.c,r)).toMatchObject({status:'UNCHANGED'});expect(f.queries.slice(n).some(q=>/^(UPDATE|INSERT)/.test(q.text)||q.text.includes('F10_TYPED_JOURNAL_START')||q.text.includes('F10_TYPED_JOURNAL_REGISTER'))).toBe(false);});
 it.each([null,'NOT_STARTED'] as const)('rejects applied metadata with journal%s, never retrospectively repairing',async state=>{const r=request(base(),true),f=transport(r,true);expect(await executeGuardedTypedLocalBackfill(f.c,r)).toMatchObject({status:'APPLIED'});if(state)f.seedJournal(state);const n=f.queries.length;expect(await executeGuardedTypedLocalBackfillWithJournal(f.c,r)).toEqual({status:'BLOCKED',code:'TYPED_JOURNAL_RETRY_STATE_DRIFT'});expect(f.queries.slice(n).some(q=>/^(UPDATE|INSERT)/.test(q.text)||q.text.includes('F10_TYPED_JOURNAL_START')||q.text.includes('F10_TYPED_JOURNAL_REGISTER'))).toBe(false);});
 it.each(['STARTED','UNKNOWN'] as const)('retains preexisting %s journal after fresh original source/target reconciliation',async state=>{const r=request(base(),true),f=transport(r,true);f.seedJournal(state);expect(await executeGuardedTypedLocalBackfillWithJournal(f.c,r)).toMatchObject({status:'APPLIED'});expect([...f.journalStates.values()].every(s=>s===state)).toBe(true);expect(f.queries.some(q=>q.text.includes('F10_TYPED_JOURNAL_REGISTER')||q.text.includes('F10_TYPED_JOURNAL_START'))).toBe(false);});
 it('storage-registration failure rolls back every journal/source/control effect',async()=>{const r=request(base(),true),f=transport(r,true);f.setMutation((tag)=>{if(tag==='JOURNAL_REGISTER')throw Error('SECRET_REGISTER_FAILURE');});expect(await executeGuardedTypedLocalBackfillWithJournal(f.c,r)).toEqual({status:'BLOCKED',code:'TYPED_JOURNAL_STORAGE_FAILED'});expect(f.journalPresent()).toBe(false);expect(f.metadata()).toEqual([null,null]);expect([...f.owners.values()].every(v=>v===null)).toBe(true);});
 it('metadata failure rolls back previously inserted journal and STARTED states together',async()=>{const r=request(base(),true),f=transport(r,true);f.setMutation((tag,rows)=>{if(tag==='DIRECT_DML')rows.length=0;});expect(await executeGuardedTypedLocalBackfillWithJournal(f.c,r)).toEqual({status:'BLOCKED',code:'DIRECT_ATTRIBUTION_NOT_EXACT'});expect(f.journalPresent()).toBe(false);expect(f.journalStates.size).toBe(0);expect(f.metadata()).toEqual([null,null]);});
 it('refuses changed or partial persisted coverage without arming metadata',async()=>{const r=request(base(),true),f=transport(r,true);f.seedJournal('STARTED');f.setMutation((tag,rows)=>{if(tag==='JOURNAL_READ'){const o=JSON.parse(rows[0][0]!);o.rows.pop();rows[0][0]=canonicalOwnershipJson(o);}});expect(await executeGuardedTypedLocalBackfillWithJournal(f.c,r)).toEqual({status:'BLOCKED',code:'TYPED_JOURNAL_DESCRIPTOR_DRIFT'});expect(f.metadata()).toEqual([null,null]);});
 it('lost COMMIT acknowledgement never issues secondary SQL and retains original plan reconciliation',async()=>{const r=request(base(),true),f=transport(r,true);f.setCommitFailure();expect(await executeGuardedTypedLocalBackfillWithJournal(f.c,r)).toEqual({status:'UNCERTAIN',code:'COMMIT_OUTCOME_UNKNOWN',planDigest:r.plan.digest,reconciliation:'FRESH_OWNED_CLIENT_ORIGINAL_PLAN_REQUIRED'});expect(f.queries.at(-1)!.text).toBe('COMMIT');});
});

// Observation-only recovery never accepts a reconstructed outcome as authority.
// These are inert transport boundaries; native JR cases prove actual SQL states.
describe('typed journal original-attempt reconciliation boundaries',()=>{
 it.each([null,undefined,{},[],{status:'UNCERTAIN',code:'COMMIT_OUTCOME_UNKNOWN',planDigest:'a'.repeat(64),reconciliation:'FRESH_OWNED_CLIENT_ORIGINAL_PLAN_REQUIRED'}])('rejects unissued uncertain receipt %j before any client read',async attempt=>{let traps=0;const hostile=new Proxy({},{get(){traps++;throw Error('SECRET');},getPrototypeOf(){traps++;throw Error('SECRET');}});expect(await reconcileGuardedTypedLocalBackfillJournal(hostile as Client,attempt)).toEqual({status:'BLOCKED',code:'TYPED_JOURNAL_ORIGINAL_UNCERTAIN_ATTEMPT_REQUIRED'});expect(traps).toBe(0);});
 it('rejects proxy/accessor/symbol receipts without observing their public data',async()=>{let traps=0;const values=[new Proxy({},{get(){traps++;throw Error('SECRET');},ownKeys(){traps++;throw Error('SECRET');},getPrototypeOf(){traps++;throw Error('SECRET');}}),{get status(){traps++;throw Error('SECRET');}},{[Symbol('receipt')]:'SECRET'}];const {c,query}=client();for(const attempt of values)expect(await reconcileGuardedTypedLocalBackfillJournal(c,attempt)).toEqual({status:'BLOCKED',code:'TYPED_JOURNAL_ORIGINAL_UNCERTAIN_ATTEMPT_REQUIRED'});expect(traps).toBe(0);expect(query).not.toHaveBeenCalled();});
 it('does not enroll uncertainty from the original journal-free entrypoint',async()=>{const r=request(base()),f=transport(r);f.setCommitFailure();const attempt=await executeGuardedTypedLocalBackfill(f.c,r);expect(attempt.status).toBe('UNCERTAIN');const fresh=client();expect(await reconcileGuardedTypedLocalBackfillJournal(fresh.c,attempt)).toEqual({status:'BLOCKED',code:'TYPED_JOURNAL_ORIGINAL_UNCERTAIN_ATTEMPT_REQUIRED'});expect(fresh.query).not.toHaveBeenCalled();});
 it('refuses originating client before SQL and preserves original uncertain result',async()=>{const r=request(base(),true),f=transport(r,true);f.setCommitFailure();const attempt=await executeGuardedTypedLocalBackfillWithJournal(f.c,r);expect(attempt).toEqual({status:'UNCERTAIN',code:'COMMIT_OUTCOME_UNKNOWN',planDigest:r.plan.digest,reconciliation:'FRESH_OWNED_CLIENT_ORIGINAL_PLAN_REQUIRED'});const boundary=f.queries.length;expect(await reconcileGuardedTypedLocalBackfillJournal(f.c,attempt)).toEqual({status:'BLOCKED',code:'TYPED_JOURNAL_FRESH_CLIENT_REQUIRED'});expect(f.queries).toHaveLength(boundary);});
 it('refuses cloned/serialized/wrapped genuine receipts before SQL',async()=>{const r=request(base(),true),f=transport(r,true);f.setCommitFailure();const attempt=await executeGuardedTypedLocalBackfillWithJournal(f.c,r);expect(attempt.status).toBe('UNCERTAIN');const fresh=client();for(const changed of [{...attempt},JSON.parse(JSON.stringify(attempt)),new Proxy(attempt,{})])expect(await reconcileGuardedTypedLocalBackfillJournal(fresh.c,changed)).toEqual({status:'BLOCKED',code:'TYPED_JOURNAL_ORIGINAL_UNCERTAIN_ATTEMPT_REQUIRED'});expect(fresh.query).not.toHaveBeenCalled();});
 it('does not enroll acknowledged successful or blocked journal results',async()=>{const r=request(base(),true),f=transport(r,true);const applied=await executeGuardedTypedLocalBackfillWithJournal(f.c,r);expect(applied.status).toBe('APPLIED');const blocked=await executeGuardedTypedLocalBackfillWithJournal(f.c,{}),fresh=client();for(const attempt of [applied,blocked])expect(await reconcileGuardedTypedLocalBackfillJournal(fresh.c,attempt)).toEqual({status:'BLOCKED',code:'TYPED_JOURNAL_ORIGINAL_UNCERTAIN_ATTEMPT_REQUIRED'});expect(fresh.query).not.toHaveBeenCalled();});
});
